// Channels in Setup settings that aren't in the table yet. A brand can have several (support, regional).
// Each new one costs one channel lookup (1 quota unit).
const key = b => String(b.vendor || '').trim().toLowerCase() + '|' + String(b.handle || '').trim().toLowerCase();
const have = new Set($input.all().map(i => i.json).filter(r => r.vendor).map(key));
return ($('Setup settings').first().json.brand_channels || [])
  .filter(b => b.vendor && b.handle && !have.has(key(b)))
  .map(b => ({ json: { vendor: String(b.vendor).trim(), handle: String(b.handle || '').trim(), domains: String(b.domains || ''), url_pattern: String(b.url_pattern || '') } }));

return $input.all().map((it, i) => {
  const b = $('New brands').itemMatching(i).json;
  const c = (it.json.body?.items || [])[0];
  return { json: { ...b, channel_id: c?.id || '', channel_name: c?.snippet?.title || '',
    note: c ? '' : 'No channel found for ' + b.handle + (it.json.body?.error ? ' (' + it.json.body.error.message + ')' : '') } };
});

