// One item per YouTube search: the brand's channel (if Setup found one), then all of YouTube.
const s = $('Find settings').first().json;
const d = $('Get products').first().json.data || {};
const list = (d.products?.nodes || d.nodes || []).filter(p => p && p.id);
const brands = $('Brand channels').all().map(i => i.json).filter(b => b.vendor);
const out = [];
for (const p of list) {
  const vendor = String(p.vendor || '').trim();
  const rows = brands.filter(b => String(b.vendor).trim().toLowerCase() === vendor.toLowerCase());
  let model = String(p.mpn?.value || '').replace(/\(.*?\)/g, '').trim(), model_from = 'model number';
  if (!model) {
    // No model number: the first title word with a digit in it (RLC-820A, C440), always reviewed.
    model = (String(p.title).split(/[\s,\/]+/).find(w => w.length >= 4 && /\d/.test(w) && /[a-z]/i.test(w) && !/^\d+(k|p|mp|mm|gb|tb)$/i.test(w)) || '');
    model_from = 'title';
  }
  const product = { product_id: p.id, product_title: p.title, handle: p.handle, vendor, model, model_from, store_url: p.onlineStoreUrl || '',
    page_url: p.page?.value || '', existing: [...(p.videos?.references?.nodes || []).map(n => n.video_id?.value || ''), ...(p.media?.nodes || []).map(m => m.originUrl || '')].join(' '),
    channels: rows.filter(b => b.channel_id).map(b => b.channel_id),
    domains: rows.flatMap(b => String(b.domains || '').split(',')).map(x => x.trim().toLowerCase()).filter(Boolean),
    url_pattern: (rows.find(b => b.url_pattern) || {}).url_pattern || '' };
  if (!model) {
    // Nothing to search for. A 1-unit call keeps the product in step with the rest, and the run row says why.
    out.push({ json: { ...product, kind: 'skip', skip_reason: 'no model number', url: 'https://www.googleapis.com/youtube/v3/videos', params: { part: 'id', id: 'none' } } });
    continue;
  }
  const withBrand = model.toLowerCase().startsWith(vendor.toLowerCase()) ? model : vendor + ' ' + model;
  for (const ch of product.channels)
    out.push({ json: { ...product, kind: 'channel', url: 'https://www.googleapis.com/youtube/v3/search',
      params: { part: 'snippet', type: 'video', channelId: ch, q: model, maxResults: s.channel_results, order: 'relevance' } } });
  out.push({ json: { ...product, kind: 'youtube', url: 'https://www.googleapis.com/youtube/v3/search',
    params: { part: 'snippet', type: 'video', q: withBrand.replace(model, '"' + model + '"'), maxResults: s.open_results,
      relevanceLanguage: s.language, regionCode: s.region_code, videoEmbeddable: 'true' } } });
}
return out;

// One item per product again, with every video id the searches found and any error.
const builds = $('Build the searches').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const by = {};
builds.forEach((b, i) => {
  const { kind, params, url, skip_reason, ...product } = b;
  const p = by[b.product_id] ||= { ...product, ids: [], errors: [], searches: 0, units: 0, skip: false };
  const r = res[i] || {}, body = r.body || {};
  if (kind === 'skip') { p.skip = true; p.errors.push(skip_reason); p.units += 1; return; }
  p.searches++; // search.list has its own bucket: 100 calls a day
  if (Number(r.statusCode) >= 400 || body.error)
    return p.errors.push('YouTube search: ' + (body.error?.errors?.[0]?.reason || body.error?.message || r.statusCode));
  (body.items || []).forEach((it, rank) => {
    if (it.id?.videoId) p.ids.push({ video_id: it.id.videoId, from: kind, rank, description: it.snippet?.description || '' });
  });
});
return Object.values(by).map(json => ({ json }));

// Plain queries (no site: operator, which DataForSEO bills at five times the price).
const s = $('Find settings').first().json;
const out = [];
for (const it of $input.all()) {
  const p = it.json;
  if (p.skip) continue;
  const q = p.model.toLowerCase().startsWith(p.vendor.toLowerCase()) ? p.model : p.vendor + ' ' + p.model;
  const task = k => [{ keyword: k, location_name: s.search_location, language_code: s.search_language, depth: 10 }];
  out.push({ json: { product_id: p.product_id, purpose: 'videos', task: task(q + ' video') } });
  if (s.use_manufacturer_page && !p.page_url && !p.url_pattern && p.domains.length)
    out.push({ json: { product_id: p.product_id, purpose: 'page', task: task(q) } });
}
return out;

// Video ids from any YouTube link in the results, and the manufacturer page: a result on one of the brand's
// websites whose path or title has the whole model code (so C440 doesn't take the C440-W page).
const tasks = $('Google searches').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const by = Object.fromEntries($('Back to products').all().map(i => [i.json.product_id, { ...i.json, ids: [...i.json.ids], errors: [...i.json.errors] }]));
const ytid = u => (String(u || '').match(/(?:youtube\.com\/(?:watch\?(?:[^#]*&)?v=|shorts\/|embed\/)|youtu\.be\/)([A-Za-z0-9_-]{11})/) || [])[1];
const norm = t => String(t || '').toUpperCase().replace(/\+/g, 'PLUS');
const compact = t => norm(t).replace(/[^A-Z0-9]/g, '');
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const host = u => ((String(u).match(/^https?:\/\/([^\/?#]+)/i) || [])[1] || '').toLowerCase();
tasks.forEach((t, i) => {
  const p = by[t.product_id];
  const task = (res[i]?.tasks || [])[0] || {};
  p.google_cost = (p.google_cost || 0) + Number(task.cost || 0);
  if (task.status_code !== 20000) return p.errors.push('Google search: ' + (task.status_message || res[i]?.error?.message || res[i]?.status_message || 'failed'));
  const items = task.result?.[0]?.items || [];
  if (t.purpose === 'videos') {
    const walk = (xs, depth = 0) => { for (const x of xs || []) {
      const id = ytid(x.url);
      if (id) p.ids.push({ video_id: id, from: 'google', rank: p.ids.length, description: x.description || '' });
      if (depth < 3) walk(x.items, depth + 1);
    } };
    return walk(items);
  }
  const code = norm(p.model).replace(/\(.*?\)/g, '').trim();
  const inTitle = s => new RegExp('(^|[^A-Z0-9])' + esc(code) + '($|[^A-Z0-9])').test(norm(s));
  const inPath = u => String(u).replace(/^https?:\/\/[^\/]+/i, '').split(/[\/?#.]/).map(compact).includes(compact(code));
  const onBrand = u => p.domains.some(d => host(u) === d || host(u).endsWith('.' + d));
  const hit = items.find(x => x.type === 'organic' && x.url && onBrand(x.url) && (inPath(x.url) || inTitle(x.title)));
  if (hit) p.google_page_url = hit.url;
});
return Object.values(by).map(json => ({ json }));

// Optional (use_manufacturer_page): YouTube videos embedded or linked on the manufacturer's own product page.
// The page comes from the Manufacturer page field, the brand's url_pattern, or the Google search.
const s = $('Find settings').first().json;
const items = $input.all().map(i => ({ ...i.json, ids: [...i.json.ids] }));
if (!s.use_manufacturer_page) return items.map(json => ({ json }));
function allowed(robots, path) { // RFC 9309, the * group: the longest matching rule wins; * is a wildcard, $ ends the path
  let on = false, best = { len: -1, allow: true };
  const hits = rule => new RegExp('^' + rule.split('*').map(x => x.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*').replace(/\\\$$/, '$')).test(path);
  for (const line of String(robots).split(/\r?\n/)) {
    const [k, ...v] = line.replace(/#.*/, '').split(':'); const key = k.trim().toLowerCase(), val = v.join(':').trim();
    if (key === 'user-agent') on = val === '*';
    else if (on && (key === 'allow' || key === 'disallow') && val && val.length > best.len && hits(val)) best = { len: val.length, allow: key === 'allow' };
  }
  return best.allow;
}
const re = /(?:youtube(?:-nocookie)?\.com\/(?:embed\/|watch\?(?:[^"'#<>\s]*?&(?:amp;)?)?v=|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{11})/g;
for (const p of items) {
  if (p.skip) continue;
  const slug = p.model.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const url = p.page_url || (p.url_pattern ? p.url_pattern.replace('{model}', slug) : '') || p.google_page_url || '';
  if (!url) { p.page_note = 'no manufacturer page'; continue; }
  const m = /^(https?:\/\/[^\/?#]+)([^#]*)/i.exec(url);
  if (!m) { p.page_note = 'bad page url'; continue; }
  try {
    let robots = '';
    try { robots = await this.helpers.httpRequest({ url: m[1] + '/robots.txt', headers: { 'User-Agent': s.user_agent }, json: false, timeout: 15000 }); } catch (e) {}
    if (!allowed(robots, m[2] || '/')) { p.page_note = 'robots.txt disallows the page'; continue; }
    const html = String(await this.helpers.httpRequest({ url, headers: { 'User-Agent': s.user_agent, Accept: 'text/html' }, json: false, timeout: 30000 }));
    const seen = new Set(); let x;
    while ((x = re.exec(html))) if (!seen.has(x[1])) { seen.add(x[1]); p.ids.push({ video_id: x[1], from: 'page', rank: seen.size, description: '' }); }
    p.page_note = seen.size + ' videos on ' + url;
  } catch (e) { p.page_note = 'page fetch failed: ' + String(e.message || e).slice(0, 120); }
}
return items.map(json => ({ json }));

// Unique ids per product, without ones already offered or already on the product. Up to 50 per videos.list call.
const known = new Set($('Known videos').all().map(i => i.json).filter(r => r.video_id).map(r => r.product_id + '|' + r.video_id));
return $('Read manufacturer pages').all().map(it => {
  const p = it.json, seen = new Set(), lookup = [], pre = { 'already offered': 0, 'already on the product': 0 };
  for (const v of p.ids) {
    if (seen.has(v.video_id)) continue;
    seen.add(v.video_id);
    if (known.has(p.product_id + '|' + v.video_id)) pre['already offered']++;
    else if (p.existing.includes(v.video_id)) pre['already on the product']++;
    else lookup.push(v.video_id);
  }
  return { json: { ...p, lookup: lookup.slice(0, 50), pre_dropped: pre } };
});

// Keeps a video only if its title (or the manufacturer's page) names this exact model and YouTube says it can be shown.
const s = $('Find settings').first().json;
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
function keys(p) {
  const raw = String(p.model || '').replace(/\(.*?\)/g, '').trim(), ks = new Set([raw]);
  for (const suf of s.ignore_suffixes || []) { const r = new RegExp('[-\\s]' + esc(suf) + '$', 'i'); if (r.test(raw)) ks.add(raw.replace(r, '')); }
  for (const k of [...ks]) for (const pre of [p.vendor, ...(s.model_prefixes || [])])
    if (pre && new RegExp('^' + esc(pre) + '[\\s-]+', 'i').test(k)) ks.add(k.replace(new RegExp('^' + esc(pre) + '[\\s-]+', 'i'), ''));
  return [...ks].filter(k => k.length >= 3 && /\d/.test(k));
}
// Whole-token match: C440 matches "VIGI C440 Setup" and "C-440", not "C440-W", "C4400" or "C440.2".
function match(p, text) {
  for (const k of keys(p)) {
    const pattern = (k.match(/[a-z]+|\d+/gi) || []).join('[\\s_-]*');
    const m = new RegExp('(^|[^a-z0-9])(' + pattern + ')(?![a-z0-9]|-[a-z0-9]|\\.\\d)', 'i').exec(String(text || ''));
    if (m) return m[2];
  }
  return null;
}
const codes = t => [...new Set((String(t).match(/\b(?=[a-z-]*\d)(?=[\d-]*[a-z])[a-z0-9]+(?:-[a-z0-9]+)*\b/gi) || [])
  .filter(c => /\d{2,}/.test(c) && !/^\d+(p|k|mp|mm|gb|tb|hz|fps|w|th|st|nd|rd|s)$/i.test(c)).map(c => c.toUpperCase().replace(/-/g, '')))];
const TYPES = [['review', /\b(review\w*|worth it|test(ed|ing)|honest|long[- ]term)\b/i], ['unboxing', /\b(unbox\w*|first (look|impressions?)|hands[- ]on|out (of )?the box)\b/i],
  ['setup', /\b(set ?up|install\w*|how to|configur\w*|tutorial|step[- ]by[- ]step|mount\w*|guide)\b/i],
  ['demo', /\b(demo|features?|overview|night vision|footage|sample|app)\b/i]];
const seconds = d => { const m = /P(?:(\d+)D)?T?(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/.exec(d || '') || []; return (+m[1] || 0) * 86400 + (+m[2] || 0) * 3600 + (+m[3] || 0) * 60 + (+m[4] || 0); };
const now = new Date().toISOString();
return $input.all().map((it, i) => {
  const p = $('Video id lists').itemMatching(i).json, r = it.json;
  const dropped = { ...p.pre_dropped }, drop = why => { dropped[why] = (dropped[why] || 0) + 1; };
  const errors = [...p.errors];
  if (Number(r.statusCode) >= 400 || r.body?.error) errors.push('YouTube details: ' + (r.body?.error?.errors?.[0]?.reason || r.statusCode));
  const found = Object.fromEntries(p.ids.map(v => [v.video_id, v]));
  const cands = [];
  for (const v of r.body?.items || []) {
    const src = found[v.id] || {}, sn = v.snippet || {}, st = v.status || {};
    const dur = seconds(v.contentDetails?.duration), lang = String(sn.defaultAudioLanguage || sn.defaultLanguage || '');
    if (!st.embeddable) { drop('not embeddable'); continue; }
    if (!['public', 'unlisted'].includes(st.privacyStatus)) { drop('private'); continue; }
    if (sn.liveBroadcastContent && sn.liveBroadcastContent !== 'none') { drop('live or upcoming'); continue; }
    if (dur < s.min_seconds) { drop('too short'); continue; }
    if (dur > s.max_seconds) { drop('too long'); continue; }
    if (lang && !lang.toLowerCase().startsWith(String(s.language).toLowerCase())) { drop('other language'); continue; }
    if (/#shorts?\b/i.test((sn.title || '') + ' ' + (sn.description || ''))) { drop('a Short (vertical)'); continue; }
    const inTitle = match(p, sn.title), inDesc = inTitle ? null : match(p, (sn.description || '') + ' ' + (src.description || ''));
    const fromPage = src.from === 'page';
    if (!inTitle && !inDesc && !fromPage) { drop('model not named'); continue; }
    const others = codes(sn.title).filter(c => c !== String(inTitle || p.model).toUpperCase().replace(/[\s-]/g, '') && !String(p.model).toUpperCase().replace(/[\s-]/g, '').includes(c));
    const comparison = /\b(vs\.?|versus|comparison|compared?)\b/i.test(sn.title) || others.length > 0;
    const video_type = comparison ? 'comparison' : (TYPES.find(([, re]) => re.test(sn.title)) || ['other'])[0];
    const is_manufacturer = p.channels.includes(sn.channelId);
    const match_source = inTitle ? 'title' : fromPage ? 'manufacturer page' : 'description';
    const coverage = comparison ? 'comparison' : (match_source === 'description' || p.model_from === 'title') ? 'uncertain' : 'exact';
    cands.push({ product_id: p.product_id, product_title: p.product_title, model: p.model, video_id: v.id, url: 'https://www.youtube.com/watch?v=' + v.id,
      title: String(sn.title || '').slice(0, 300), channel_id: sn.channelId || '', channel_name: sn.channelTitle || '', is_manufacturer,
      duration_s: dur, views: Number(v.statistics?.viewCount || 0), published_at: sn.publishedAt || null, language: lang || 'unknown',
      match_quote: inTitle || inDesc || p.model, match_source, video_type, coverage, status: 'pending', found_at: now,
      score: (is_manufacturer ? 4 : 0) + (fromPage ? 4 : 0) + (inTitle ? 2 : 0) + (coverage === 'exact' ? 1 : 0) });
  }
  // Best first, then one of each type before a second of any type (a setup video and a review beat three unboxings).
  cands.sort((a, b) => b.score - a.score || b.views - a.views);
  const keep = [], types = new Set();
  for (const c of cands) if (keep.length < s.max_videos_per_product && !types.has(c.video_type)) { keep.push(c); types.add(c.video_type); }
  for (const c of cands) if (keep.length < s.max_videos_per_product && !keep.includes(c)) keep.push(c);
  if (cands.length > keep.length) dropped['not in the top ' + s.max_videos_per_product] = cands.length - keep.length;
  for (const c of keep) delete c.score;
  return { json: { product_id: p.product_id, product_title: p.product_title, model: p.model, searches: p.searches, quota_units: p.units + 1,
    found: p.lookup.length, kept: keep.length, dropped, keep, error: errors.join('; '), page_note: p.page_note || '' } };
});

const s = $('Find settings').first().json;
const esc = t => String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const LABELS = { exact: 'This product', comparison: 'Comparison (several products)', mention: 'Brief mention', uncertain: 'Not sure yet' };
const TYPES = { setup: 'Setup tutorial', review: 'Review', unboxing: 'Unboxing', comparison: 'Comparison', demo: 'Feature demo', other: 'Video' };
const dur = n => `${Math.floor(n / 60)}:${String(n % 60).padStart(2, '0')}`;
const num = n => n >= 1e6 ? (n / 1e6).toFixed(1) + 'M' : n >= 1e3 ? Math.round(n / 1e3) + 'K' : String(n);
return $input.all().map(it => {
  const v = it.json, opt = k => ({ text: { type: 'plain_text', text: LABELS[k] }, value: k });
  const match = v.match_source === 'title' ? `Matched *${esc(v.match_quote)}* in the video title.`
    : v.match_source === 'manufacturer page' ? 'On the manufacturer\'s product page.'
    : `*${esc(v.match_quote)}* is only in the description. Check it's this model.`;
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: ('Video for ' + v.product_title).slice(0, 150) } },
    { type: 'section', text: { type: 'mrkdwn', text: `*<${v.url}|${esc(v.title).replace(/\|/g, ' ')}>*\n` + (v.is_manufacturer ? ':white_check_mark: Manufacturer channel: ' : 'Channel: ') + esc(v.channel_name) } },
    { type: 'image', image_url: `https://i.ytimg.com/vi/${v.video_id}/hqdefault.jpg`, alt_text: String(v.title).slice(0, 2000) },
    { type: 'context', elements: [{ type: 'mrkdwn', text: [TYPES[v.video_type], dur(v.duration_s), num(v.views) + ' views',
      'published ' + String(v.published_at || '').slice(0, 10), v.language === 'unknown' ? 'language not set' : v.language].join(' · ') }] },
    { type: 'section', text: { type: 'mrkdwn', text: match + (v.video_type === 'comparison' ? '\nIt names other models too: probably a comparison.' : '') } },
    { type: 'input', block_id: 'field_coverage', optional: true, label: { type: 'plain_text', text: 'What does it cover?' },
      element: { type: 'static_select', action_id: 'coverage', options: Object.keys(LABELS).map(opt), initial_option: opt(v.coverage) } },
    { type: 'context', block_id: 'video_hint', elements: [{ type: 'mrkdwn', text: 'Watch it first: the checks read the title, channel and YouTube\'s settings, not the video.' }] },
    { type: 'actions', block_id: 'video_actions', elements: [
      { type: 'button', text: { type: 'plain_text', text: 'Watch' }, url: v.url, action_id: 'video_watch' },
      { type: 'button', style: 'primary', text: { type: 'plain_text', text: 'Approve' }, action_id: 'video_approve', value: String(v.id) },
      { type: 'button', style: 'danger', text: { type: 'plain_text', text: 'Reject' }, action_id: 'video_reject', value: String(v.id) }] },
  ];
  return { json: { row_id: v.id, card: JSON.stringify(blocks),
    body: { channel: s.slack_channel, text: `Video for ${v.product_title}: ${v.title}`, blocks, unfurl_links: false, unfurl_media: false } } };
});

// Reads the raw body first: Slack signs the exact bytes it sent. (A Set node before this would drop them.)
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || '';
let p = {};
try { p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' '))); } catch (e) {}
const a = p.actions?.[0] || {};
return [{ json: {
  base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'] || '',
  fresh: Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) <= 300, retry: !!h['x-slack-retry-num'],
  app_id: p.api_app_id || '', user_id: p.user?.id || '', response_url: p.response_url || '',
  action: String(a.action_id || '').replace(/^video_/, ''), row_id: Number(a.value) || 0,
  coverage: p.state?.values?.field_coverage?.coverage?.selected_option?.value || '' } }];

const s = $('Publish settings').first().json;
let rows = $input.all().map(i => i.json).filter(r => r.id);
if (s.product_id) rows = rows.filter(r => r.product_id === s.product_id);
return rows.slice(0, s.batch_size).map(json => ({ json }));

// Refuses a video that changed since someone approved it.
return $('Claim it').all().map((it, i) => {
  const r = it.json, v = ($input.all()[i].json.body?.items || [])[0];
  let problem = '';
  if (!v) problem = 'The video is gone or private now.';
  else if (!v.status?.embeddable) problem = 'The video can no longer be embedded.';
  else if (v.snippet?.title !== r.title || v.snippet?.channelId !== r.channel_id) problem = 'Its title or channel changed since review.';
  return { json: { ...r, problem } };
});

// dry_run is on: the video entry Publish would save, and nothing else.
return $input.all().map(i => ({ json: { product: i.json.product_title, handle: 'video-' + i.json.id, fields: {
  title: i.json.title, video_id: i.json.video_id, url: i.json.url, channel_name: i.json.channel_name, coverage: i.json.coverage, video_type: i.json.video_type } } }));

