});
const live = $input.all().map(i => i.json).filter(r => r.id && r.metaobject_id);
const order = (a, b) => (b.is_manufacturer === true) - (a.is_manufacturer === true) || String(a.decided_at).localeCompare(String(b.decided_at));
const by = {};
for (const r of saved) (by[r.product_id] ||= { product_id: r.product_id, rows: [] }).rows.push(r);
return Object.values(by).map(p => {
  const ids = [...live.filter(r => r.product_id === p.product_id), ...p.rows.filter(r => r.metaobject_id)].sort(order).map(r => r.metaobject_id);
  return { json: { ...p, ids: [...new Set(ids)] } };
});

