// Back to one item per video, marked added only when Shopify's list now holds its entry.
const out = [];
$input.all().forEach((it, i) => {
  const p = $('Video lists').all()[i].json, res = it.json;
  const errors = [...(res.errors || []), ...(res.data?.metafieldsSet?.userErrors || [])].map(e => e.message);
  const mf = (res.data?.metafieldsSet?.metafields || [])[0] || {};
  const listed = String(mf.value || '');
  const owner = mf.owner || {};
  for (const r of p.rows) {
    const added = !!r.metaobject_id && listed.includes(r.metaobject_id);
    out.push({ json: { ...r, added, store_url: owner.onlineStoreUrl || owner.onlineStorePreviewUrl || '', store_is_preview: !owner.onlineStoreUrl,
      error: added ? '' : (r.error || errors.join('; ') || 'Shopify didn\'t save the video list.') } });
  }
});
return out;

const rows = $input.all().map(i => i.json).filter(r => r.video_id);
const out = [];
for (let i = 0; i < rows.length; i += 50) out.push({ json: { rows: rows.slice(i, i + 50), ids: rows.slice(i, i + 50).map(r => r.video_id).join(',') } });
return out;

// A video YouTube no longer returns was deleted or made private. A failed call is skipped, never read as "gone".
const gone = [];
$input.all().forEach((it, i) => {
  const b = $('Batch the ids').itemMatching(i).json, r = it.json;
  if (Number(r.statusCode) >= 400 || r.body?.error) return;
  const now = Object.fromEntries((r.body?.items || []).map(v => [v.id, v]));
  for (const row of b.rows) {
    const v = now[row.video_id];
    const reason = !v ? 'deleted or made private' : !v.status?.embeddable ? 'embedding turned off' : v.snippet?.channelId !== row.channel_id ? 'moved to another channel' : '';
    if (reason) gone.push({ json: { ...row, reason } });
  }
});
return gone;

// One item per product that lost a video: the live videos it still has, in the same order Publish uses.
const gone = $('What changed?').all().map(i => i.json);
const live = $input.all().map(i => i.json).filter(r => r.id && r.metaobject_id);
const order = (a, b) => (b.is_manufacturer === true) - (a.is_manufacturer === true) || String(a.decided_at).localeCompare(String(b.decided_at));
return [...new Set(gone.map(r => r.product_id))].map(product_id => ({ json: { product_id,
  ids: live.filter(r => r.product_id === product_id).sort(order).map(r => r.metaobject_id) } }));

